import numpy as np
from itertools import product

def get_k_for_all_subsets(N, s):
    M = N - s + 1
    if M <= 0: return 0
    max_k = 0
    # There are 2^(M*M) possible configurations of n_{r,c} in {0, 1}
    for subset in product([0, 1], repeat=M*M):
        n = np.array(subset).reshape((M, M))
        counts = np.zeros((N, N), dtype=int)
        for r in range(M):
            for c in range(M):
                if n[r, c] == 1:
                    counts[r:r+s, c:c+s] += 1

        nonzero_counts = counts[counts > 0]
        if len(nonzero_counts) > 0:
            vals, counts_val = np.unique(nonzero_counts, return_counts=True)
            max_k = max(max_k, np.max(counts_val))
    return max_k

print("N=3, s=2, max_k =", get_k_for_all_subsets(3, 2))
print("N=4, s=2, max_k =", get_k_for_all_subsets(4, 2))
print("N=5, s=2, max_k =", get_k_for_all_subsets(5, 2))
print("N=5, s=3, max_k =", get_k_for_all_subsets(5, 3))

